/**
 * The app's icons, Phosphor's (phosphoricons.com, MIT), the owner's choice among four sets: filled
 * and rounded, read well from the sofa; the outline weight where an icon is a state that is off
 * (a star not given, a list the title is not on), the bold one for line-only shapes (arrows, a
 * check, a cross). Kept as their 256-unit paths: a whole icon library for some fifty shapes would
 * be most of the APK on a box with little storage.
 */
object Icons {
  private fun icon(name: String, d: String): ImageVector =
      ImageVector.Builder(name, 24.dp, 24.dp, 256f, 256f)
          .addPath(PathParser().parsePathString(d).toNodes(), fill = SolidColor(Color.White))
          .build()

